local HoneyDipperMaker = {}
local PRODUCTS = {
    iron_honeydipper = { name = "Železni medna zajemalka", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni medna zajemalka za kuhinjo." },
    bronze_honeydipper = { name = "Bronast medna zajemalka", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast medna zajemalka za kuhinjo." },
    silver_honeydipper = { name = "Srebrn medna zajemalka", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn medna zajemalka za kuhinjo." },
    gilded_honeydipper = { name = "Pozlačen medna zajemalka", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen medna zajemalka za kuhinjo." },
    jewel_set_honeydipper = { name = "Draguljast medna zajemalka", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast medna zajemalka za kuhinjo." },
    royal_sovereign_honeydipper = { name = "Kraljevski suveren medna zajemalka", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren medna zajemalka z biseri za krono." },
}
local BUILDINGS = {
    honeydipper_workshop = { name = "Honeydipper delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    honeydipper_house = { name = "Honeydipper hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_honeydipper_atelier = { name = "Mojstrski honeydipper atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_honeydipper_palace = { name = "Suverena honeydipper palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
HoneyDipperMaker.ironStock = 10; HoneyDipperMaker.bronzeStock = 8; HoneyDipperMaker.woodStock = 18; HoneyDipperMaker.leatherStock = 10; HoneyDipperMaker.silverStock = 8; HoneyDipperMaker.goldStock = 6; HoneyDipperMaker.jewelStock = 4; HoneyDipperMaker.pearlStock = 4
HoneyDipperMaker.productStock = {}; HoneyDipperMaker.buildings = {}; HoneyDipperMaker.maker = nil; HoneyDipperMaker.activeMaking = {}; HoneyDipperMaker.totalProducts = 0; HoneyDipperMaker.dayTimer = 0
function HoneyDipperMaker.init() HoneyDipperMaker.ironStock=10; HoneyDipperMaker.bronzeStock=8; HoneyDipperMaker.woodStock=18; HoneyDipperMaker.leatherStock=10; HoneyDipperMaker.silverStock=8; HoneyDipperMaker.goldStock=6; HoneyDipperMaker.jewelStock=4; HoneyDipperMaker.pearlStock=4; HoneyDipperMaker.productStock={}; HoneyDipperMaker.buildings={}; HoneyDipperMaker.maker=nil; HoneyDipperMaker.activeMaking={}; HoneyDipperMaker.totalProducts=0; HoneyDipperMaker.dayTimer=0; print("[HoneyDipperMaker] Royal Honey Dipper Maker System initialized (6 products, 4 buildings)") end
function HoneyDipperMaker.hireMaker(n,s) s=s or math.random(55,90); local c=565+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HoneyDipperMaker.maker={name=n or ("Medar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Medar najet: %s (spretnost: %d)",HoneyDipperMaker.maker.name,s),"success") end; return true end
function HoneyDipperMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HoneyDipperMaker.build(id) local ok,e=HoneyDipperMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HoneyDipperMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HoneyDipperMaker.getQualityBonus() local b=0; for _,bd in ipairs(HoneyDipperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HoneyDipperMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and HoneyDipperMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and HoneyDipperMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and HoneyDipperMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and HoneyDipperMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and HoneyDipperMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HoneyDipperMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HoneyDipperMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and HoneyDipperMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #HoneyDipperMaker.buildings==0 then return false,"Potrebna medna delavnica" end; if not HoneyDipperMaker.maker then return false,"Potreben medar" end; return true end
function HoneyDipperMaker.make(pt,qty) qty=qty or 1; local ok,e=HoneyDipperMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then HoneyDipperMaker.ironStock=HoneyDipperMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then HoneyDipperMaker.bronzeStock=HoneyDipperMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then HoneyDipperMaker.woodStock=HoneyDipperMaker.woodStock-d.woodCost*qty end; if d.leatherCost then HoneyDipperMaker.leatherStock=HoneyDipperMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then HoneyDipperMaker.silverStock=HoneyDipperMaker.silverStock-d.silverCost*qty end; if d.goldCost then HoneyDipperMaker.goldStock=HoneyDipperMaker.goldStock-d.goldCost*qty end; if d.jewelCost then HoneyDipperMaker.jewelStock=HoneyDipperMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then HoneyDipperMaker.pearlStock=HoneyDipperMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if HoneyDipperMaker.maker then t=math.max(1,t-math.floor(HoneyDipperMaker.maker.skill/13)) end; table.insert(HoneyDipperMaker.activeMaking,{id="honeydipper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HoneyDipperMaker.completeMaking(m) local q=1.0+(HoneyDipperMaker.getQualityBonus()/100); if HoneyDipperMaker.maker then q=q+(HoneyDipperMaker.maker.skill/140) end; q=math.min(2.5,q); HoneyDipperMaker.productStock[m.productType]=(HoneyDipperMaker.productStock[m.productType] or 0)+m.quantity; HoneyDipperMaker.totalProducts=HoneyDipperMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HoneyDipperMaker.maker then HoneyDipperMaker.maker.itemsMade=HoneyDipperMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then HoneyDipperMaker.maker.skill=math.min(100,HoneyDipperMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zajemalka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"honeydipper.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function HoneyDipperMaker.update(dt) if not _G.state then return end; HoneyDipperMaker.dayTimer=HoneyDipperMaker.dayTimer+dt; if HoneyDipperMaker.dayTimer>=30 then HoneyDipperMaker.dayTimer=0; for i=#HoneyDipperMaker.activeMaking,1,-1 do local m=HoneyDipperMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HoneyDipperMaker.completeMaking(m); table.remove(HoneyDipperMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HoneyDipperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HoneyDipperMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HoneyDipperMaker.getStats() return {ironStock=HoneyDipperMaker.ironStock,bronzeStock=HoneyDipperMaker.bronzeStock,woodStock=HoneyDipperMaker.woodStock,leatherStock=HoneyDipperMaker.leatherStock,silverStock=HoneyDipperMaker.silverStock,goldStock=HoneyDipperMaker.goldStock,jewelStock=HoneyDipperMaker.jewelStock,pearlStock=HoneyDipperMaker.pearlStock,productStock=HoneyDipperMaker.productStock,numBuildings=#HoneyDipperMaker.buildings,hasMaker=HoneyDipperMaker.maker~=nil,makerName=HoneyDipperMaker.maker and HoneyDipperMaker.maker.name or "—",makerSkill=HoneyDipperMaker.maker and HoneyDipperMaker.maker.skill or 0,activeMaking=#HoneyDipperMaker.activeMaking,totalProducts=HoneyDipperMaker.totalProducts} end
return HoneyDipperMaker
